package com.acme.orders.controller; import com.acme.orders.dto.*; import com.acme.orders.service.OrderService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/orders") public class OrderController {private final OrderService service;public OrderController(OrderService service){this.service=service;}@GetMapping public java.util.List<OrderResponse> all(){return service.all();}@PostMapping @ResponseStatus(HttpStatus.CREATED) public OrderResponse create(@Valid @RequestBody CreateOrderRequest r){return service.create(r);}}
